mapper.select:
select * from book

    status = #{status}

        and (title like concat('%', #{keyword}, '%') or author like concat('%', #{keyword}, '%') or isbn like concat('%', #{keyword}, '%'))

    and category_id = #{categoryId}
    and `condition` = #{condition}
    and price >= #{minPrice}
    and price <= #{maxPrice}
    and university = #{university}

order by create_time desc
